"""Invoice total calculation utilities."""

TAX_PERCENT = 9


def _round_half_up(numerator, denominator):
    """Divide two nonnegative ints, rounding half up to the nearest unit."""
    return (numerator + denominator // 2) // denominator


def total(amounts):
    """Return the invoice total in cents.

    ``amounts`` holds nonnegative integer cent values. A 9 percent tax is
    applied to the subtotal and the result is rounded half up to a cent.
    The input list is not modified.
    """
    subtotal = 0
    for amount in amounts:
        if isinstance(amount, bool) or not isinstance(amount, int):
            raise TypeError("amounts must contain integer cents")
        if amount < 0:
            raise ValueError("amounts must be nonnegative")
        subtotal += amount

    return _round_half_up(subtotal * (100 + TAX_PERCENT), 100)

