TAX_PERCENT = 9


def _round_half_up(numerator, denominator):
    """Round the nonnegative fraction numerator/denominator to the nearest
    integer, rounding exact halves up."""
    return (2 * numerator + denominator) // (2 * denominator)


def total(amounts):
    """Return the invoice total in cents, including a 9% tax.

    ``amounts`` is an iterable of nonnegative integer cents. The sum is taxed
    at 9% and the result is rounded half up to a whole cent. The input
    sequence is not modified.
    """
    subtotal = sum(amounts)
    return _round_half_up(subtotal * (100 + TAX_PERCENT), 100)

